# src/report.pyimport osimport refrom datetime import datetimefrom reportlab.lib import colorsfrom reportlab.lib.enums import TA_LEFTfrom reportlab.lib.pagesizes import A4from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheetfrom reportlab.lib.units import mmfrom reportlab.platypus import (PageBreak, Paragraph, SimpleDocTemplate, Spacer,                                Table, TableStyle)INK = colors.HexColor("#1C1A17")MUTED = colors.HexColor("#62594A")RULE = colors.HexColor("#DCD5C6")PANEL = colors.HexColor("#FFFDF8")PASS_C = colors.HexColor("#27511F")FAIL_C = colors.HexColor("#7E2817")MISS_C = colors.HexColor("#6A4E0B")PAGE_W, PAGE_H = A4MARGIN = 18 * mmUSABLE = PAGE_W - (2 * MARGIN)def _clean(text) -> str:    """Strip markdown and typographic characters that read as machine output."""    if text is None:        return ""    s = str(text)    s = re.sub(r"\*\*(.+?)\*\*", r"\1", s)      # bold    s = re.sub(r"(?<!\w)\*(.+?)\*(?!\w)", r"\1", s)  # italics    s = s.replace("###", "").replace("##", "").replace("#", "")    s = s.replace("\u2014", ", ").replace("\u2013", "-")   # em / en dash    s = s.replace("\u2212", "-")                            # minus sign    s = s.replace("\u2018", "'").replace("\u2019", "'")    s = s.replace("\u201c", '"').replace("\u201d", '"')    s = s.replace("\u2022", "")                             # stray bullets    s = re.sub(r"[ \t]+", " ", s)    return s.strip()def _styles():    base = getSampleStyleSheet()    return {        "title": ParagraphStyle("vtitle", parent=base["Title"], fontName="Times-Bold",                                fontSize=24, leading=28, textColor=INK,                                alignment=TA_LEFT, spaceAfter=2),        "sub": ParagraphStyle("vsub", parent=base["Normal"], fontName="Times-Italic",                              fontSize=10.5, leading=14, textColor=MUTED),        "meta": ParagraphStyle("vmeta", parent=base["Normal"], fontName="Helvetica",                               fontSize=8.5, leading=12, textColor=MUTED),        "h2": ParagraphStyle("vh2", parent=base["Normal"], fontName="Times-Bold",                             fontSize=13, leading=16, textColor=INK,                             spaceBefore=4, spaceAfter=8),        "th": ParagraphStyle("vth", parent=base["Normal"], fontName="Helvetica-Bold",                             fontSize=7, leading=9, textColor=MUTED),        "cell": ParagraphStyle("vcell", parent=base["Normal"], fontName="Helvetica",                               fontSize=7.5, leading=10, textColor=INK),        "cellmut": ParagraphStyle("vcellmut", parent=base["Normal"], fontName="Helvetica",                                  fontSize=7, leading=9.5, textColor=MUTED),        "sid": ParagraphStyle("vsid", parent=base["Normal"], fontName="Helvetica-Bold",                              fontSize=7, leading=9, textColor=INK),        "body": ParagraphStyle("vbody", parent=base["Normal"], fontName="Helvetica",                               fontSize=9, leading=13.5, textColor=INK, spaceAfter=3),        "tip": ParagraphStyle("vtip", parent=base["Normal"], fontName="Helvetica",                              fontSize=9, leading=13, textColor=INK,                              leftIndent=10, bulletIndent=2, spaceAfter=2),        "foot": ParagraphStyle("vfoot", parent=base["Normal"], fontName="Helvetica",                               fontSize=6.5, leading=9, textColor=MUTED),    }def _status_color(status: str):    s = str(status).upper()    return {"PASS": PASS_C, "FAIL": FAIL_C, "MISSING": MISS_C}.get(s, MUTED)def _results_table(results_df, st_):    cols = ["specimen_id", "lot", "status", "rationale"]    widths = [USABLE * 0.26, USABLE * 0.08, USABLE * 0.10, USABLE * 0.56]    data = [[Paragraph("SPECIMEN", st_["th"]), Paragraph("LOT", st_["th"]),             Paragraph("STATUS", st_["th"]), Paragraph("RATIONALE", st_["th"])]]    for _, r in results_df[cols].iterrows():        rationale = _clean(r["rationale"]).replace("; ", "<br/>")        data.append([            Paragraph(_clean(r["specimen_id"]), st_["sid"]),            Paragraph(_clean(r["lot"]), st_["cellmut"]),            Paragraph(str(r["status"]).upper(), st_["cell"]),            Paragraph(rationale, st_["cellmut"]),        ])    tbl = Table(data, colWidths=widths, repeatRows=1)    style = [        ("VALIGN", (0, 0), (-1, -1), "TOP"),        ("LINEBELOW", (0, 0), (-1, 0), 0.9, INK),        ("LINEBELOW", (0, 1), (-1, -1), 0.3, RULE),        ("TOPPADDING", (0, 0), (-1, -1), 6),        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),        ("LEFTPADDING", (0, 0), (-1, -1), 4),        ("RIGHTPADDING", (0, 0), (-1, -1), 4),    ]    for i, (_, r) in enumerate(results_df[cols].iterrows(), start=1):        style.append(("TEXTCOLOR", (2, i), (2, i), _status_color(r["status"])))    tbl.setStyle(TableStyle(style))    return tbldef _explanation_flowables(sid, text, st_):    out = [Paragraph(_clean(sid), st_["h2"])]    cleaned = _clean(text)    cleaned = re.sub(r"\s*(PASS/FAIL Summary|Summary|Remediation Tips|Tips)\s*:\s*",                     " ", cleaned, flags=re.IGNORECASE)    parts = re.split(r"(?:(?<=\.)|^)\s*\d\.\s+", cleaned)    parts = [p.strip() for p in parts if p.strip()]    if parts:        out.append(Paragraph(parts[0], st_["body"]))        for p in parts[1:]:            out.append(Paragraph(p, st_["tip"], bulletText="\u2013"))    out.append(Spacer(1, 8))    return outdef make_pdf(results_df, template_meta, explanations, out_path="ComplianceReport.pdf"):    st_ = _styles()    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M")    std = template_meta.get("standard_id", "STD")    ver = template_meta.get("version", "1.0")    try:        from src.provider import DEFAULT_MODEL        model_name = DEFAULT_MODEL    except Exception:        model_name = os.environ.get("VERA_MODEL", "unspecified")    mode = os.environ.get("LLM_MODE", "CLOUD")    doc = SimpleDocTemplate(        out_path, pagesize=A4,        leftMargin=MARGIN, rightMargin=MARGIN,        topMargin=MARGIN, bottomMargin=MARGIN,        title="VERA Compliance Report", author="VERA",    )    story = [        Paragraph("VERA", st_["title"]),        Paragraph("Validation and Explanation for Regulatory Assurance", st_["sub"]),        Spacer(1, 10),    ]    total = len(results_df)    n_pass = int((results_df["status"] == "PASS").sum())    n_fail = int((results_df["status"] == "FAIL").sum())    n_miss = int((results_df["status"] == "MISSING").sum())    header = Table(        [[Paragraph(f"<b>Standard</b><br/>{_clean(std)} v{_clean(ver)}", st_["meta"]),          Paragraph(f"<b>Specimens</b><br/>{total}", st_["meta"]),          Paragraph(f"<b>Pass</b><br/>{n_pass}", st_["meta"]),          Paragraph(f"<b>Fail</b><br/>{n_fail}", st_["meta"]),          Paragraph(f"<b>Missing</b><br/>{n_miss}", st_["meta"]),          Paragraph(f"<b>Generated</b><br/>{timestamp}", st_["meta"])]],        colWidths=[USABLE * w for w in (0.26, 0.13, 0.13, 0.13, 0.15, 0.20)],    )    header.setStyle(TableStyle([        ("VALIGN", (0, 0), (-1, -1), "TOP"),        ("BACKGROUND", (0, 0), (-1, -1), PANEL),        ("BOX", (0, 0), (-1, -1), 0.3, RULE),        ("TOPPADDING", (0, 0), (-1, -1), 7),        ("BOTTOMPADDING", (0, 0), (-1, -1), 7),        ("LEFTPADDING", (0, 0), (-1, -1), 7),    ]))    story += [header, Spacer(1, 16),              Paragraph("Specimen results", st_["h2"]),              _results_table(results_df, st_)]    if explanations:        story += [Spacer(1, 18), Paragraph("Explanations", st_["h2"])]        for sid, text in explanations.items():            story += _explanation_flowables(sid, text, st_)    story += [        Spacer(1, 14),        Paragraph(            f"Checks are deterministic and evaluated from the template above. "            f"Explanations are generated by {model_name} ({mode}) and grounded only in the "            f"listed measurements. Template: {_clean(std)} v{_clean(ver)}. Generated {timestamp}.",            st_["foot"]),    ]    doc.build(story)    return out_path